const [bitmask, triage] = await Promise.allSettled([
  tools["ardupilot-research"].decode_bitmask({ param: "RC_OPTIONS", value: "0x2000" }),
  tools["ardupilot-research"].troubleshoot({ symptom: "tắt failsafe mất tín hiệu radio để nó khỏi báo" }),
]);
return { bitmask, triage };

